# 0~6300번대의 기존 번역에는 후속 분석으로 확정된 인명 표기가 일부
# 남아 있었다. 원문 전체에 적용해 앞·뒤 장면의 표기를 하나로 통일한다.
LEGACY_REPLACEMENTS = (
    ("시라카와 이치로", "시라카와 이치리"),
    ("하리마 나오마사", "하리마 나오타다"),
    ("나오마사", "나오타다"),
    ("미즈나키", "미나즈키"),
    ("이치로", "이치리"),
)
EARLY_OVERRIDES = {
    1570: r"【아사츠유】\n아버지는 시라카와 사토루야.\n즉, 피해자의 조카인 셈이지.",
}
MAX_DIALOGUE_WIDTH = 19


def wrap_dialogue(text: str) -> str:
    """Keep each rendered line inside the game's 19-cell dialogue width.

    A literal ``\\n`` is part of the TSV format, so wrapping works on those escaped
    lines and emits the same representation. Spaces are preferred as break points;
    unspaced strings are split at the cell limit. This does not alter the wording,
    only where the engine advances to the next rendered line.
    """
    wrapped: list[str] = []
    for segment in text.split(r"\n"):
        segment = segment.strip() if segment.startswith(" ") and segment.endswith(" ") else segment
        while len(segment) > MAX_DIALOGUE_WIDTH:
            candidates = [index for index, char in enumerate(segment[: MAX_DIALOGUE_WIDTH + 1])
                          if char == " "]
            if candidates and candidates[-1] >= 8:
                cut = candidates[-1]
                wrapped.append(segment[:cut].rstrip())
                segment = segment[cut + 1 :].lstrip()
            else:
                wrapped.append(segment[:MAX_DIALOGUE_WIDTH])
                segment = segment[MAX_DIALOGUE_WIDTH:]
        wrapped.append(segment)
    return r"\n".join(wrapped)


def read_tsv(path: Path) -> list[dict[str, str]]:
    with path.open("r", encoding="utf-8-sig", newline="") as handle:
        return list(csv.DictReader(handle, delimiter="\t"))


def write_tsv(path: Path, rows: list[dict[str, str]]) -> None:
    with path.open("w", encoding="utf-8", newline="") as handle:
        writer = csv.DictWriter(
            handle,
            fieldnames=["offset", "lines", "text"],
            delimiter="\t",
            lineterminator="\n",
        )
        writer.writeheader()
        writer.writerows(rows)


def main() -> None:
    source = read_tsv(SOURCE)
    rows = read_tsv(TARGET)
    assert len(source) == len(rows) == 9626
    assert set(MANUAL) == set(range(6301, 9626))

    changes: list[dict[str, object]] = []
    for order, new_text in MANUAL.items():
        old_text = rows[order]["text"]
        rows[order]["text"] = new_text
        rows[order]["lines"] = str(new_text.count(r"\n") + 1)
        changes.append(
            {
                "order": order,
                "offset": rows[order]["offset"],
                "source_ja": source[order]["text"],
                "old_translation": old_text,
                "new_translation": new_text,
                "status": "manual_context_retranslation",
                "emulator_launched": False,
            }
        )

    for order, new_text in EARLY_OVERRIDES.items():
        old_text = rows[order]["text"]
        rows[order]["text"] = new_text
        rows[order]["lines"] = str(new_text.count(r"\n") + 1)
        changes.append(
            {
                "order": order,
                "offset": rows[order]["offset"],
                "source_ja": source[order]["text"],
                "old_translation": old_text,
                "new_translation": new_text,
                "status": "final_kanji_context_correction",
                "confirmed_kanji": "姪",
                "emulator_launched": False,
            }
        )

    for order, row in enumerate(rows):
        old_text = row["text"]
        new_text = wrap_dialogue(old_text)
        if new_text == old_text:
            continue
        row["text"] = new_text
        row["lines"] = str(new_text.count(r"\n") + 1)
        changes.append(
            {
                "order": order,
                "offset": row["offset"],
                "source_ja": source[order]["text"],
                "old_translation": old_text,
                "new_translation": new_text,
                "status": "dialogue_width_wrap",
                "width_limit": MAX_DIALOGUE_WIDTH,
                "emulator_launched": False,
            }
        )

    for order, row in enumerate(rows):
        old_text = row["text"]
        new_text = old_text
        for old_fragment, new_fragment in LEGACY_REPLACEMENTS:
            new_text = new_text.replace(old_fragment, new_fragment)
        if new_text == old_text:
            continue
        row["text"] = new_text
        row["lines"] = str(new_text.count(r"\n") + 1)
        changes.append(
            {
                "order": order,
                "offset": row["offset"],
                "source_ja": source[order]["text"],
                "old_translation": old_text,
                "new_translation": new_text,
                "status": "confirmed_name_normalization",
                "emulator_launched": False,
            }
        )

    write_tsv(TARGET, rows)
    REPORT.write_text(
        json.dumps(
            {
                "schema": "enkaku_retranslation_v2_manual_rest_report",
                "source_range": {
                    "order_start": min(MANUAL),
                    "order_end": max(MANUAL),
                    "count": len(MANUAL),
                },
                "rows": len(rows),
                "changed": len(changes),
                "translations": changes,
                "emulator_launched": False,
            },
            ensure_ascii=False,
            indent=2,
        )
        + "\n",
        encoding="utf-8",
    )
    print(json.dumps({"rows": len(rows), "changed": len(changes), "emulator_launched": False}, ensure_ascii=False))


if __name__ == "__main__":
    main()
